import healthcare;

class VitalSigns {
    blood_pressure: int;
    heart_rate: int;
}

class LabResults {
    total_cholesterol: int;
}

class Patient {
    patient_id: string;
    age: int;
    gender: string;
    vital_signs: VitalSigns;
    lab_results: LabResults;
}

let vitals := new VitalSigns {
    blood_pressure := 130,
    heart_rate     := 70,
};

let labs := new LabResults {
    total_cholesterol := 190,
};

let patient := new Patient {
    patient_id  := "PAT003",
    age         := 47,
    gender      := "M",
    vital_signs := vitals,
    lab_results := labs,
};

let validation := validate_patient_data(patient);
println(validation);

let risk := analyze_heart_disease(patient);
println(risk);

